import { createContext, useContext, useState, ReactNode, HTMLAttributes } from 'react';

interface TabsContextValue {
  activeIndex: number;
  setActiveIndex: (index: number) => void;
  items: { id: string; label: string }[];
}

const TabsContext = createContext<TabsContextValue | null>(null);

function useTabsContext() {
  const ctx = useContext(TabsContext);
  if (!ctx) throw new Error('Tabs compound components must be used inside <Tabs>');
  return ctx;
}

// Parent component
interface TabsProps {
  items: { id: string; label: string }[];
  defaultIndex?: number;
  children: ReactNode;
}

function Tabs({ items, defaultIndex = 0, children }: TabsProps) {
  const [activeIndex, setActiveIndex] = useState(defaultIndex);

  return (
    <TabsContext.Provider value={{ activeIndex, setActiveIndex, items }}>
      <div className="tabs-container">{children}</div>
    </TabsContext.Provider>
  );
}

// Child: Tab
interface TabProps extends HTMLAttributes<HTMLElement> {
  index: number;
}

function Tab({ index, children, ...rest }: TabProps) {
  const { activeIndex, setActiveIndex } = useTabsContext();
  const isActive = activeIndex === index;

  return (
    <button
      role="tab"
      aria-selected={isActive}
      onClick={() => setActiveIndex(index)}
      className={`tab ${isActive ? 'tab-active' : ''}`}
      {...rest}
    >
      {children}
    </button>
  );
}

// Child: Panel
interface PanelProps extends HTMLAttributes<HTMLElement> {
  index: number;
}

function Panel({ index, children, ...rest }: PanelProps) {
  const { activeIndex } = useTabsContext();
  if (activeIndex !== index) return null;

  return (
    <div role="tabpanel" className="tab-panel" {...rest}>
      {children}
    </div>
  );
}

Tabs.Tab = Tab;
Tabs.Panel = Panel;

export { Tabs };
